# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MUHAMMEDÜ\'L-EMÎN VE HZ. HATİCE İLE EVLİLİĞİ (MİLADİ 595)</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TİCARET HAYATI VE GÜVENİLİRLİK</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Lakabı: Muhammedü\'l-Emîn (Sözü ve özü en güvenilir kişi).</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Hz. Hatice\'nin Lakabı: Tâhire (İffetli ve tertemiz hanım).</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Şam Kervanı: Yardımcısı Meysere ile Busra ticaret seferi.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Gözlem: Meysere\'nin O\'nun dürüstlüğüne ve ahlakına şahitliği.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Sonuç: Ticari güven ve üstün ahlak evliliğin temelini attı.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">ÖRNEK AİLE YUVASI VE EV HALKI</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Evlilik Tarihi: Miladi 595 (Hz. Muhammed 25 yaşında).</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Süre: Hz. Hatice\'nin vefatına (620) kadar 25 yıl tek eşlilik.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Sosyal Dayanışma: Kıtlık yılında Ebû Tâlib\'in yükünü hafifletmek</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• için amcasının oğlu Hz. Ali\'yi kendi evine alıp büyütmesi.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Zeyd b. Hârise\'yi azat ederek evlat edinmesi ve şefkati.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Hatice, ilk vahiy geldiğinde Hz. Peygamber\'i ilk tasdik eden ve malıyla-canıyla destekleyen ilk Müslüman\'dır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. PEYGAMBER\'İN (SAV) ÇOCUKLARI VE SOYUNUN DEVAMI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ERKEK ÇOCUKLARI (KÜÇÜK YAŞTA VEFAT ETTİLER)</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• 1. Kâsım: İlk çocuğudur (Künyesi: Ebü\'l-Kâsım).</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• 2. Abdullah: Lakapları \'Tâhir\' ve \'Tayyib\'dir (Hz. Hatice\'den).</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• 3. İbrahim: Medine\'de Hz. Mâriye\'den doğan en küçük oğlu.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• İmtihan: Erkek çocuklarının vefatı üzerine müşriklerin \'ebter\'</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• alayına karşı Kevser suresi indirilerek teselli edilmiştir.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">KIZ ÇOCUKLARI (TAMAMI HZ. HATİCE\'DEN)</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• 1. Hz. Zeyneb (En büyük kızı, Ebü\'l-Âs ile evlendi).</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• 2. Hz. Rukıyye ve 3. Hz. Ümmü Gülsüm (Hz. Osman ile evlendi).</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• 4. Hz. Fâtıma: Babasının vefatından sonra yaşayan tek çocuğu.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Soyun Devamı: Hz. Fâtıma ve Hz. Ali\'nin evliliğinden doğan</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Hz. Hasan (şerifler) ve Hz. Hüseyin (seyyidler) ile sürdü.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber kızı Hz. Fâtıma yanına geldiğinde ayağa kalkar, alnından öper ve onu kendi yerine oturturdu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KÂBE HAKEMLİĞİ VE TOPLUMSAL BARIŞ ÇÖZÜMÜ (MİLADİ 605)</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">KRİZİN ORTAYA ÇIKIŞI (HACERÜ\'L-ESVED)</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Tarih: Miladi 605 (Hz. Muhammed 35 yaşında, risaletten 5 yıl önce).</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Sebep: Sel ve yangından zarar gören Kâbe\'nin tamiri.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Sorun: Hacerü\'l-Esved\'i yerine koyma şerefi için kabile kavgası.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Tehlike: Kabilelerin kan çanağına el batırıp savaş yemini etmesi.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Öneri (Ebû Ümeyye): Kapıdan ilk girenin hakem seçilmesi.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">EL-EMÎN\'İN HAKEMLİĞİ VE ADİL ÇÖZÜM</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Tepki: \'İşte Muhammedü\'l-Emîn! Onun hükmüne razıyız!\'</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Yöntem: Hacerü\'l-Esved\'in geniş bir örtü (ridâ) üzerine konması.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• Katılım: Tüm kabile reislerinin örtünün uçlarından tutması.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Uygulama: Taşı kendi elleriyle duvardaki yerine yerleştirmesi.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Sonuç: Tüm kabileler onurlandırıldı ve kan dökülmesi önlendi.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kâbe Hakemliği, Hz. Peygamber\'in kriz çözme, adaleti sağlama ve toplumu ortak paydada birleştirme dehasını gösterir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
